  it("p_expr", () => {
    const x = new Sym('x');
    expect(sympyStr(QQ.polyRing(x).toSympy(new PolyRing([x], QQ, 'lex').fromExpr(add(1, mul(rational(1, 3), pow(x, 2)))).asExpr()))).toBe('x**2/3 + 1');
  });
  // text that is not a string
